package com.example

import com.example.ExamQuestionHelper.QSpec

internal object BuddhismG11LiveExamEthicsBank1 {
  private const val T = "බෞද්ධ සදාචාරය, ගිහි විනය හා සමාජ දර්ශනය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("ගිහි බෞද්ධයාගේ නිත්‍ය ශීලය ලෙස හඳුන්වනු ලබන්නේ කුමක්ද?", "පංච ශීලය", "අෂ්ටාංග උපෝසථ ශීලය", "දස ශීලය", "පාතිමෝක්ෂ ශීලය", "සමාජ සුරක්ෂිතතාව තහවුරු කරන මූලික ශික්ෂා පද පහ නිත්‍ය ශීලයයි."),
    q("පංච ශීලයේ පළමු ශික්ෂා පදයෙන් සුරක්ෂිත කෙරෙන මූලික මානව අයිතිවාසිකම කුමක්ද?", "ජීවත් වීමේ අයිතිය", "දේපළ අයිතිය", "භාෂණයේ නිදහස", "සංචාරක නිදහස", "ප්‍රාණඝාතයෙන් වැළකීමෙන් සියලු සත්වයන්ගේ ජීවිත ආරක්ෂාව තහවුරු වේ."),
    q("පංච ශීලයේ දෙවන ශික්ෂා පදය වන අදත්තාදානයෙන් වැළකීම මගින් තහවුරු වන්නේ කුමක්ද?", "පුද්ගල දේපළ ආරක්ෂාව", "පවුල් සංස්ථාව", "සත්‍යවාදී බව", "සිහිනුවණ", "නුදුන් දේ නොගැනීමෙන් සමාජයේ ආර්ථික හා දේපළ සුරක්ෂිතතාව ඇති වේ."),
    q("කාමමිථ්‍යාචාරයෙන් වැළකීමේ තෙවන ශික්ෂා පදය මගින් ආරක්ෂා වන ප්‍රධාන සමාජ ආයතනය කුමක්ද?", "පවුල් සංස්ථාව", "රාජ්‍ය භාණ්ඩාගාරය", "වෙළඳපොළ", "අධිකරණ පද්ධතිය", "අඹුසැමි විශ්වාසය හා පවුලේ සමගිය තෙවන සිල් පදයෙන් සුරැකේ."),
    q("සිව්වන සිල්පදය වන මුසාවාදයෙන් වැළකීම තුළින් සමාජයට ලැබෙන ප්‍රධාන යහපත කුමක්ද?", "අන්‍යෝන්‍ය විශ්වාසය හා සත්‍යවාදී බව", "බොහෝ මුදල් ලැබීම", "විනෝදාස්වාදය", "බලය තහවුරු වීම", "වචනයේ පිරිසිදුකම නිසා සමාජ සබඳතාවල විශ්වාසනීයත්වය වර්ධනය වේ."),
    q("පස්වන සිල්පදය රැකීමෙන් මිනිසාට ආරක්ෂා කරගත හැකි වටිනාම සම්පත කුමක්ද?", "සිහිනුවණ හා සමාජ ගෞරවය", "ශරීර වර්ණය පමණක්", "කීර්ති නාමය පමණක්", "මිතුරන් ගණන", "මත්පැන් හා මත්ද්‍රව්‍යවලින් වැළකීමෙන් සිහිය විකල් වීම හා අපරාධ වළකී."),
    q("පෝය දිනවලදී ගිහියන් විසින් සමාදන් වන 'අෂ්ටාංග උපෝසථ ශීලයේ' තෙවන සිල්පදය කුමක්ද?", "අබ්‍රහ්මචරියාවෙන් වැළකීම", "කාමමිථ්‍යාචාරයෙන් වැළකීම", "මුසාවාදයෙන් වැළකීම", "විකාල භෝජනයෙන් වැළකීම", "උපෝසථ ශීලයේදී කාමමිථ්‍යාචාරය වෙනුවට සම්පූර්ණ බ්‍රහ්මචරියාව රකියි."),
    q("අෂ්ටාංග ශීලයේ සයවන ශික්ෂා පදයෙන් වළකින්නේ කුමකින්ද?", "විකාල භෝජනයෙන් (නොකල්හි ආහාර ගැනීමෙන්)", "මත්ද්‍රව්‍ය භාවිතයෙන්", "නැටුම් ගැයුම් බැලීමෙන්", "උසසුන් මහසුන් පරිහරණයෙන්", "මධ්‍යාහ්නය ඉක්මවූ පසු රාත්‍රී ආහාරයෙන් වැළකීම විකාල භෝජන විරමණයයි."),
    q("නැටුම්, ගැයුම්, වැයුම්, විසුළු දසුන් බැලීමෙන් හා මල් ගඳ විලවුන් දැරීමෙන් වැළකීම අෂ්ටාංග ශීලයේ කීවන සිල්පදයද?", "හත්වන සිල්පදය", "හයවන සිල්පදය", "අටවන සිල්පදය", "පස්වන සිල්පදය", "ඉන්ද්‍රිය සංවරය උදෙසා නච්ච ගීත වාදිත සිල්පදය පනවා ඇත."),
    q("උස් අසුන් හා මහ අසුන් පරිහරණයෙන් වැළකීම උපෝසථ ශීලයේ අටවන සිල්පදය වන්නේ කුමක් පුහුණු කිරීමටද?", "නිහතමානීකම හා අල්පේච්ඡතාව", "කායික ව්‍යායාමය", "සමාජ තත්ත්වය පෙන්වීම", "ධනය ඉතිරි කිරීම", "සැප පහසුකම්වල ඇලීම අඩු කර සරල ජීවිතයකට හුරුවීමයි."),
    q("සමාජ සංහිඳියාව ගොඩනගන 'සතර සංග්‍රහ වස්තු' මොනවාද?", "දාන, ප්‍රියවචන, අර්ථචර්යා, සමානාත්මතා", "මෙත්තා, කරුණා, මුදිතා, උපේක්ඛා", "සද්ධා, සීල, චාග, පඤ්ඤා", "ලෝභ, ද්වේෂ, මෝහ, මාන", "සතර සංග්‍රහ වස්තු සමාජයේ සුහදතාව රඳවන රථයේ ඇණයට උපමා කර ඇත."),
    q("සතර සංග්‍රහ වස්තු අතර 'අර්ථචර්යා' යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "අන් අයගේ දියුණුව හා යහපත උදෙසා ක්‍රියා කිරීම", "ආහාර පාන පමණක් දීම", "මිහිරි වචන කතා කිරීම", "සම සේ අසුන් ගැනීම", "සමාජයේ අනෙක් අයට උපකාරී වන අභිවෘද්ධිදායක සේවාවන් ඉටු කිරීමයි."),
    q("සමානාත්මතාව යන සංග්‍රහ වස්තුවෙන් බුදුදහම අපේක්ෂා කරන්නේ කුමක්ද?", "කුල, ජාති, ධන භේදයකින් තොරව සැමට සමානව සැලකීම", "තමා උසස් කොට සැලකීම", "පොහොසතුන්ට පමණක් ගරු කිරීම", "විශේෂ වරප්‍රසාද ලබා ගැනීම", "අනුන්ද තමා හා සමාන කොට සලකා උපකාර කිරීම සමානාත්මතාවයි."),
    q("පාලකයන් හා විනිසුරුවන් නොයා යුතු වැරදි මාර්ග හතර ලෙස දැක්වෙන 'සතර අගතිය' මොනවාද?", "ඡන්ද, දෝස, භය, මෝහ", "රාග, ද්වේෂ, මෝහ, මාන", "ජාති, ජරා, ව්‍යාධි, මරණ", "දාන, සීල, භාවනා, ප්‍රඥා", "පක්ෂග්‍රාහීව තීරණ ගැනීමට තුඩු දෙන අගති හතරෙන් වැළකීම යුක්තිගරුක සමාජයක ලක්ෂණයකි."),
    q("තමා කැමති හිතවතා නිසා වැරදි තීරණයක් ගැනීම කවර අගතියට අයත්ද?", "ඡන්දාගතිය", "දෝසාගතිය", "භයාගතිය", "මෝහාගතිය", "ප්‍රිය පුද්ගලයන් කෙරෙහි ඇති ඇල්ම නිසා අසාධාරණ ලෙස ක්‍රියා කිරීම ඡන්දාගතියයි."),
    q("කෙනෙකු කෙරෙහි ඇති තරහව හෝ වෛරය නිසා අසාධාරණ තීන්දු ගැනීම කවර අගතියද?", "දෝසාගතිය", "ඡන්දාගතිය", "භයාගතිය", "මෝහාගතිය", "ද්වේෂය හේතුවෙන් සාධාරණය යටපත් කිරීම දෝසාගතියයි."),
    q("බලවතෙකුට හෝ නින්දාවකට බිය වී වැරදි තීරණයක් ගැනීම කුමන අගතියද?", "භයාගතිය", "මෝහාගතිය", "ඡන්දාගතිය", "දෝසාගතිය", "බලපෑම්වලට බියෙන් යුක්තිය පාවා දීම භයාගතියයි."),
    q("කරුණු හරිහැටි සොයා නොබලා නොදැනුවත්කම නිසා වැරදි තීරණ ගැනීම කුමන අගතියද?", "මෝහාගතිය", "භයාගතිය", "දෝසාගතිය", "ඡන්දාගතිය", "අනුවණකම නිසා සත්‍යය වටහා නොගෙන තීරණ ගැනීම මෝහාගතියයි."),
    q("කායික, වාචසික හා මානසික වශයෙන් සිදුවන වැරදි ක්‍රියා 'දස අකුසල්' ලෙස බෙදේ. ඉන් කයින් සිදුවන අකුසල් ගණන කීයද?", "තුනකි", "හතරකි", "දෙකකි", "පහකි", "ප්‍රාණඝාතය, අදත්තාදානය, කාමමිථ්‍යාචාරය කාය කර්ම තුනයි."),
    q("දස අකුසල් අතර වචනයෙන් සිදුවන අකුසල කර්ම හතර මොනවාද?", "මුසාවාද, පිසුණාවාචා, ඵරුසාවාචා, සම්ඵප්පලාප", "ප්‍රාණඝාත, අදත්තාදාන, සුරාපාන, මුසාවාද", "අභිජ්ඣා, ව්‍යාපාද, මිච්ඡාදිට්ඨි, මාන", "ලෝභ, ද්වේෂ, මෝහ, ඊර්ෂ්‍යා", "බොරු කීම, කේළාම් කීම, පරුෂ වචන කීම හා හිස් වචන කීම වචී අකුසල් හතරයි."),
    q("අනුන්ගේ සමගිය බිඳෙන ලෙස කේළාම් කීම පාලි ධර්මයේ හඳුන්වන්නේ කුමන නමින්ද?", "පිසුණාවාචා", "ඵරුසාවාචා", "සම්ඵප්පලාප", "මුසාවාද", "දෙදෙනෙකු අතර භේද ඇති කරන කේළාම් කීම පිසුණාවාචා නම් වේ."),
    q("කිසිදු අර්ථයක් හෝ ප්‍රයෝජනයක් නැති හිස් දෙඩවීම් හඳුන්වන වචී අකුසලය කුමක්ද?", "සම්ඵප්පලාප", "පිසුණාවාචා", "ඵරුසාවාචා", "මුසාවාද", "කාලය හා අර්ථය විනාශ කරන නිසරු කතා සම්ඵප්පලාප වේ."),
    q("දස අකුසල්වල මනසින් සිදුවන අකුසල කර්ම තුන මොනවාද?", "අභිජ්ඣා, ව්‍යාපාද, මිච්ඡාදිට්ඨි", "ලෝභ, කේළාම්, ප්‍රාණඝාත", "මුසාවාද, සොරකම, රාගය", "මානය, ඊර්ෂ්‍යාව, අලසකම", "අනුන් සතු දේට දැඩි ලෙස ලොල් වීම, අනුන් නැසේවායි සිතීම හා වැරදි දැක්ම මනෝ අකුසල් තුනයි."),
    q("බෞද්ධ දේශපාලන දර්ශනයේ පාලකයෙකු සතු විය යුතු 'දස රාජ ධර්ම' වල පළමු ධර්මය කුමක්ද?", "දානය", "සීලය", "පරිච්චාගය", "අජ්ජවය", "රාජ්‍ය පාලකයා ජනතා සුබසිද්ධිය උදෙසා දානශීලී විය යුතුය."),
    q("දස රාජ ධර්ම අතර 'අජ්ජව' හා 'මද්දව' යන ගුණාංග දෙකේ අර්ථය කුමක්ද?", "ඍජු බව හා මෘදු මොළොක් බව", "දැඩි බව හා රළු බව", "වංචනික බව හා බිය", "මසුරු බව හා කෝපය", "පාලකයා අවංක, ඍජු හා ජනතාවට සංවේදී මෘදු කෙනෙකු විය යුතුය."),
    q("දස රාජ ධර්මවල 'තපස්' (තපෝ) යන ගුණයෙන් පාලකයෙකුගෙන් අපේක්ෂා කරන්නේ කුමක්ද?", "චාම් සරල ජීවිතයක් ගත කර ඉන්ද්‍රිය සංවරය රැකීම", "වනයට ගොස් මිය යාම", "ජනතාවට දඬුවම් කිරීම", "රාජකාරි අතහැරීම", "කාමභෝගී සුඛෝපභෝගීත්වයට ගිජු නොවී ආදර්ශමත් සරල පැවැත්මයි."),
    q("දස රාජ ධර්මවල 'අවිරෝධතාව' යනුවෙන් අදහස් කරන්නේ කුමක්ද?", "ජනමතයට හා ධර්ම නීතියට විරුද්ධ නොවී සමගියෙන් කටයුතු කිරීම", "සියලු නීති කඩ කිරීම", "යුද්ධ ඇති කිරීම", "ජනතාව පීඩාවට පත් කිරීම", "මහජන හිතසුව හා යුක්තිය සමඟ නොගැටී පාලනය ගෙන යෑමයි."),
    q("බෞද්ධ සාහිත්‍යයේ දැක්වෙන 'සක්විති වත්' (චක්‍රවර්ති ව්‍රත) අතර ප්‍රධාන වන්නේ කුමක්ද?", "ධර්මය ගුරු කොටගෙන සැමට ධාර්මික රැකවරණය සැලසීම", "අසල්වැසි රටවල් ආක්‍රමණය කිරීම", "අධික බදු අය කිරීම", "සතුන් බිලි පූජා පැවැත්වීම", "ධර්මං යේව ගරුං කත්වා යනුවෙන් රටවැසියා, සේනාව, වන සතුන් හා පක්ෂීන් පවා රැකිය යුතුය."),
    q("වජ්ජි ජනරජයේ දියුණුවට හේතු වූ 'සප්ත අපරිහානීය ධර්ම' බුදුරදුන් දෙසුවේ කා හටද?", "වජ්ජි රජදරුවන් අරභයා ආනන්ද හිමිට හා වස්සකාර ඇමතිට", "බිම්බිසාර රජුට", "කොසොල් රජුට", "චණ්ඩපජ්ජෝත රජුට", "සමූහාණ්ඩු පාලනයක ස්ථාවරත්වයට බලපාන ප්‍රජාතන්ත්‍රවාදී ධර්ම 7 ක් වදාළහ."),
    q("සප්ත අපරිහානීය ධර්මවල පළමු කරුණ වන්නේ කුමක්ද?", "නිතර රැස්වී සාකච්ඡා කිරීම (අභිණ්හ සන්නිපාත)", "රහසින් තීරණ ගැනීම", "පැරණි නීති කඩ කිරීම", "වැඩිහිටියන් නොසලකා හැරීම", "නිරන්තර සාකච්ඡාවෙන් හා සමගියෙන් රැස්වී තීරණ ගැනීමයි."),
    q("සප්ත අපරිහානීය ධර්මවල 'සමග්ගා සන්නිපතන්ති සමග්ගා වුට්ඨහන්ති' යන්නෙන් අදහස් වන්නේ කුමක්ද?", "සමගියෙන් රැස්වී, සමගියෙන් විසිරී, සමගියෙන් කටයුතු කිරීම", "විවාද කරමින් වෙන් වීම", "තනි මතයට වැඩ කිරීම", "රැස්වීම් වර්ජනය කිරීම", "සාමූහික තීරණ හා සමගිය රාජ්‍යයක නොපිරිහීමට හේතු වේ."),
    q("සප්ත අපරිහානීය ධර්මවල සඳහන් වැඩිහිටියන්ට සැලකීම පිළිබඳ නීතිය කුමක්ද?", "මහලු වැඩිහිටියන්ට ගරු කර ඔවුන්ගේ උපදෙස් ඇසිය යුතු බව", "වැඩිහිටියන් පිටුවහල් කළ යුතු බව", "තරුණයන් පමණක් පාලනය කළ යුතු බව", "අතීත චාරිත්‍ර ඉවත දැමිය යුතු බව", "පළපුරුදු වැඩිහිටියන්ගේ අත්දැකීම් අගය කිරීම සමාජ සුරක්ෂිතතාවට වැදගත්ය."),
    q("බුදුදහමේ කුල භේදය ප්‍රතික්ෂේප කරමින් 'චත්තාරෝ මේ වණ්ණා' (වර්ණ හතරම සමාන බව) දෙසූ සූත්‍රය කුමක්ද?", "මධුර සූත්‍රය (හා අස්සලායන සූත්‍රය)", "රතන සූත්‍රය", "ආලවක සූත්‍රය", "ධජග්ග සූත්‍රය", "කුලයෙන් උසස් පහත් බවක් නොමැති බව මහාකච්චායන හිමි හා බුදුරදුන් තර්කානුකූලව පෙන්වූහ."),
    q("මනුෂ්‍ය සමාජයේ සියලු දෙනාම ජීව විද්‍යාත්මකව එකම වර්ගයකට අයත් බව බුදුරදුන් දෙසුවේ කුමන සූත්‍රයේද?", "වාසෙට්ඨ සූත්‍රයේ", "රෝහිතස්ස සූත්‍රයේ", "ධම්මචක්ක සූත්‍රයේ", "සල්ලේඛ සූත්‍රයේ", "ගස් වැල් හා සතුන් අතර මෙන් මිනිසුන් අතර උපතින් විවිධ ජාති නොමැති බව පෙන්වූහ."),
    q("බෞද්ධ සමාජයේ විවාහ ජීවිතය සාර්ථක කර ගැනීමට නකුලපිතා හා නකුලමාතාට බුදුරදුන් දෙසූ සමාන ගුණ හතර කුමක්ද?", "සමසද්ධා, සමසීල, සමචාග, සමපඤ්ඤා", "සමරූප, සමධන, සමකුල, සමබල", "දාන, ප්‍රියවචන, අර්ථචර්යා, සමානාත්මතා", "මෛත්‍රී, කරුණා, මුදිතා, උපේක්ෂා", "ශ්‍රද්ධාව, ශීලය, පරිත්‍යාගය හා ප්‍රඥාව සමාන නම් මෙලොව පරලොව දෙකේම එක්ව සතුටු විය හැක."),
    q("කාන්තාවගේ ගෞරවය හා අයිතිය තහවුරු කරමින් බුදුරදුන් කොසොල් රජුට දූ උපත ගැන වදාළේ කුමක්ද?", "නුවණැති සිල්වත් දියණිය පිරිමි දරුවෙකුට වඩා ශ්‍රේෂ්ඨ විය හැකි බව", "දියණියකගේ උපත දුකක් බව", "දියණියකට පැවිද්ද නොලැබෙන බව", "කාන්තාවට අධ්‍යාපනය අනවශ්‍ය බව", "මල්ලිකා දේවියට දියණියක උපන් විට කනගාටු වූ කොසොල් රජුට කාන්තා අගය වදාළහ."),
    q("මිනිසෙකු උසස් වන්නේ උපන් ජාතියෙන් නොව ගුණදහමින් බව පෙන්වන 'සුනීත හිමිගේ' චරිතයෙන් කියවෙන්නේ කුමක්ද?", "සමාජ අසාධාරණය හා කුල පීඩනය බුදු සසුන තුළ නොමැති බව", "කුලීන අයට පමණක් පැවිද්ද ඇති බව", "ධනවතුන්ට පමණක් නිවන් ඇති බව", "කසළ ශෝධකයන්ට විහාරයට යෑම තහනම් බව", "චාතුර්වණ්ණා සුද්ධිය පෙන්වමින් සෑම කුලයකම අයට සම අවස්ථා හිමි විය."),
    q("පස් පව්වලින් වැළකී සමාජයේ යහපැවැත්ම රැක ගැනීමට ගිහියන් පිළිපැදිය යුතු 'සද්පුරිස ධර්ම' වලට අයත් ගුණයක් කුමක්ද?", "කළගුණ සැලකීම (කතඤ්ඤුතා කතවේදිතා)", "මසුරුකම", "කෝපය", "ප්‍රමාදය", "උපකාර කළ අය සිහි කර ප්‍රතිඋපකාර දැක්වීම සත්පුරුෂ ධර්මයකි."),
    q("බුදුරදුන්ගේ ඉගැන්වීම් අනුව නියම 'කෘතවේදීත්වය' පෙන්වීම සඳහා තම මව්පියන්ට කළ හැකි උසස්ම උපකාරය කුමක්ද?", "ශ්‍රද්ධාව, ශීලය, චාගය හා ප්‍රඥාව යන ධර්මයන්හි පිහිටුවීම", "මිල මුදල් පමණක් දීම", "රසවත් ආහාර පමණක් දීම", "විශාල නිවසක් තැනීම පමණක්", "කතඤ්ඤුතා සූත්‍රයේදී මව්පියන් උරමත තබා පෝෂණය කළත් ඔවුන් දහමේ පිහිටුවීම උතුම් බව වදාළහ."),
    q("විවාද හා ගැටුම් පවතින සමාජයක සාමය ඇති කිරීමට බුදුදහමේ දැක්වෙන 'සාරාණීය ධර්ම' ගණන කීයද?", "හයකි", "හතරකි", "අටකි", "දසයකි", "මෙත්තා කායකම්ම, වචීකම්ම, මනෝකම්ම, සාධාරණ පරිභෝගය, සීල සාමඤ්ඤතා, දිට්ඨි සාමඤ්ඤතා සයයි."),
    q("සාරාණීය ධර්ම හයෙන් ප්‍රකාශ කෙරෙන ප්‍රධාන සමාජ පරමාර්ථය කුමක්ද?", "ප්‍රියභාවය, ගෞරවය, සමගිය හා අවිවාදය ඇති කිරීම", "ධනය බෙදා ගැනීමේ ගැටුම් ඇති කිරීම", "පෞද්ගලික ලාභය පමණක් සෙවීම", "බලය අත්පත් කර ගැනීම", "කෝසම්බියේ භික්ෂූන් අරභයා දෙසූ මෙම ධර්ම සමාජ සමගියට මඟ පාදයි."),
    q("සමාජයක මනුෂ්‍ය සබඳතා රැක ගැනීමට වැළකිය යුතු 'පංච වෛර' වලට අයත් නොවන්නේ කුමක්ද?", "මෛත්‍රියෙන් කතා කිරීම", "ප්‍රාණඝාතය", "සොරකම", "සුරාපානය", "පංච දුශ්චරිතය හෙවත් පංච වෛරයෙන් වැළකීමෙන් භය වෛර සංසිඳේ."),
    q("ගිහි බෞද්ධයෙකු තම ජීවිතයේදී වර්ධනය කරගත යුතු 'සප්ත ආර්ය ධනය' අතරට අයත් නොවන්නේ කුමක්ද?", "ලෝභ ධනය", "සද්ධා ධනය", "සීල ධනය", "හිරි හා ඔත්තප්ප ධනය", "සද්ධා, සීල, හිරි, ඔත්තප්ප, සුත, චාග, පඤ්ඤා සප්ත ආර්ය ධනයයි."),
    q("සප්ත ආර්ය ධනයේ 'සුත ධනය' යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "බහුශ්‍රැත බව හෙවත් ධර්ම ශාස්ත්‍රීය දැනුම", "ධාන්‍ය සම්පත්තිය", "රන් ආභරණ", "ඉඩකඩම්", "බොහෝ ඇසූ පිරූ තැන් ඇති උගත්කම සුත ධනයයි."),
    q("බෞද්ධ අධ්‍යාපන දර්ශනය අනුව දැනුම පමණක් නොව චරිත සංවර්ධනයද අවශ්‍ය බව පෙන්වන්නේ කුමකින්ද?", "විජ්ජා හා චරණ යන දෙකම සම්පූර්ණ වීමෙන්", "ධනය හා බලයෙන්", "කීර්තිය හා ලාභයෙන්", "විභාග සමත් වීමෙන් පමණක්", "නිවැරදි දැනුම (විජ්ජා) හා යහපත් හැසිරීම (චරණ) සමාජයට වැඩදායී පුද්ගලයෙකු තනයි."),
    q("බුදුරදුන් සමයේ විසූ බාලදරුවන්ගේ හා තරුණයන්ගේ විනය හා අධ්‍යාපනය වෙනුවෙන් වැදගත් වූ සූත්‍රය කුමක්ද?", "සිඟාලෝවාද සූත්‍රය", "ආදිත්තපරියාය සූත්‍රය", "සත්තසූරියුග්ගමන සූත්‍රය", "නාලක සූත්‍රය", "ගුරු-ශිෂ්‍ය හා මව්පිය-දූදරු යුතුකම් සිඟාලෝවාද සූත්‍රයේ පැහැදිලිව දැක්වේ."),
    q("බෞද්ධ සමාජයේ සෑම ක්‍රියාවකම සදාචාරාත්මක අගය මැනීමට බුදුරදුන් රාහුල හිමිට දෙසූ 'අම්බලට්ඨිකා රාහුලෝවාද සූත්‍රයේ' උපමාව කුමක්ද?", "කැඩපතක උපමාව", "පහනක උපමාව", "රථයක උපමාව", "ගසක උපමාව", "කැඩපතකින් මුහුණ බලන්නාක් මෙන් කය, වචනය, සිත යන ක්‍රියා කරන විට හා පසුව විමසා බැලිය යුතුය."),
    q("අම්බලට්ඨිකා රාහුලෝවාද සූත්‍රයට අනුව ක්‍රියාවක් කිරීමට පෙර විමසිය යුතු ප්‍රධාන කරුණ කුමක්ද?", "මෙය තමාටත් අනුන්ටත් හිංසාවක් හෝ අහිතක් වේදැයි විමසීම", "එයින් මුදල් ලැබේදැයි බැලීම", "අනුන් ප්‍රශංසා කරයිදැයි බැලීම", "ඉක්මනින් අවසන් කළ හැකිදැයි බැලීම", "අත්තව්‍යාබාධාය, පරව්‍යාබාධාය යන දෙඅංශයටම හානි නොවන ක්‍රියා පමණක් කළ යුතුය."),
    q("වැරදි ක්‍රියාවක් කළ පසු එය නිවැරදි කර ගැනීමට රාහුලෝවාද සූත්‍රයේ දෙන උපදේශය කුමක්ද?", "ගුරුවරයෙකු හෝ සබ්‍රහ්මචාරීන් ඉදිරියේ වරද පිළිගෙන ඉන් වැළකීම", "වරද සඟවා තබා ගැනීම", "අනුන්ට දොස් පැවරීම", "පලා යෑම", "වරද හෙළිදරව් කර ආයති සංවරයේ පිහිටීම දියුණුවේ ලක්ෂණයකි."),
    q("බෞද්ධ සමාජ චාරිත්‍ර අතර වැඩිහිටියන්ට හා ගුරුවරුන්ට ගෞරව කිරීම සඳහා භාවිත කරන ක්‍රමවේදයක් නොවන්නේ කුමක්ද?", "අත්පොළසන් දී සිනාසීම", "අභිවාදනය (වැඳීම)", "පච්චුට්ඨානය (හුනස්නෙන් නැගිටීම)", "අඤ්ජලිකම්මය (දොහොත් මුදුන් දී නමස්කාරය)", "අභිවාදන, පච්චුට්ඨාන, අඤ්ජලිකම්ම, සාමීචිකම්ම ගෞරව දැක්වීමේ ආකාර වේ."),
    q("සදාචාර සම්පන්න පුද්ගලයෙකු සතු 'අභිවාදනසීලිස්ස' ගුණයෙන් වැඩෙන ආයු වර්ණ සැප බල යන සතර වැඩෙන්නේ කාටද?", "සිල්වත් වැඩිහිටියන්ට නිරන්තරයෙන් වැඳුම් පිදුම් ගෞරව කරන්නාට", "ධනවතුන්ට පමණක් කතා කරන්නාට", "නිතර සටන් කරන්නාට", "අලසව සිටින්නාට", "වැඩිහිටියන් පිදීමෙන් ආයු, වර්ණ, සුඛ, බල යන ධර්ම සතර වර්ධනය වන බව ධම්මපදයේ එයි.")
  )
}
